tain >0.8 mg"}, {"evidence_id": "I3", "title": "Chapter 8: Dental Health Education and Promotion", "content": "Modeling behavior can facilitate learning through imitation."}], "allowed_evidence_ids": ["I1", "I2", "I3"]}
